create function pg_temp.as_user(who text,level text default 'aal1') returns void language plpgsql as $$begin perform set_config('request.jwt.claim.sub',current_setting('aura.'||case when who='admin' then 'admin' else 'uid'||who end),true);perform set_config('request.jwt.claims',jsonb_build_object('sub',auth.uid(),'session_id',current_setting('aura.'||case when who='admin' then 'sidadmin' else 'sid'||who end),'aal',level)::text,true);end$$;
create function pg_temp.check_ok(v boolean,description text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',description;end if;perform set_config('aura.test_count',(coalesce(nullif(current_setting('aura.test_count',true),''),'0')::int+1)::text,true);end$$;
create function pg_temp.denied(action text,clinic uuid,body jsonb,wanted text default '42501') returns void language plpgsql as $$declare code text;begin begin perform public.aura_rpc(action,clinic,body);exception when others then get stacked diagnostics code=returned_sqlstate;end;perform pg_temp.check_ok(code=wanted,'deny '||action||' expected '||wanted||' got '||coalesce(code,'success'));end$$;
